import hashlib


def build(
    label: Gtk.TextBuffer | None, alias_slug: GLib.Variant | None
) -> MutterDisplayManager | DisplayManager | LegacyDisplayManager:
    """Return True if the SHA-256 digest of the file at file_path matches expected_sha256."""
